CREATE TABLE public.us_cities (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  city text NOT NULL,
  admin_name text NOT NULL,
  state_code text NOT NULL,
  lat numeric(9, 6) NOT NULL,
  lng numeric(9, 6) NOT NULL,
  population bigint NOT NULL CHECK (population >= 0)
);

CREATE INDEX us_cities_city_lower_prefix_idx
  ON public.us_cities (lower(city) text_pattern_ops);

ALTER TABLE public.us_cities ENABLE ROW LEVEL SECURITY;

CREATE OR REPLACE FUNCTION public.search_us_cities(
  search_query text,
  result_limit integer DEFAULT 10
)
RETURNS TABLE (
  id bigint,
  city text,
  admin_name text,
  state_code text,
  display_name text,
  lat numeric,
  lng numeric,
  population bigint
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  WITH normalized AS (
    SELECT lower(trim(search_query)) AS query,
           least(greatest(coalesce(result_limit, 10), 1), 10) AS max_results
  )
  SELECT
    cities.id,
    cities.city,
    cities.admin_name,
    cities.state_code,
    cities.city || ', ' || cities.state_code AS display_name,
    cities.lat,
    cities.lng,
    cities.population
  FROM public.us_cities AS cities
  CROSS JOIN normalized
  WHERE normalized.query <> ''
    AND lower(cities.city) LIKE '%' || normalized.query || '%'
  ORDER BY
    CASE
      WHEN lower(cities.city) = normalized.query THEN 0
      WHEN lower(cities.city) LIKE normalized.query || '%' THEN 1
      ELSE 2
    END,
    cities.population DESC,
    cities.city,
    cities.admin_name
  LIMIT (SELECT max_results FROM normalized);
$$;

REVOKE ALL ON FUNCTION public.search_us_cities(text, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.search_us_cities(text, integer) TO anon, authenticated;

